import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    k = int(input[1])
    problems = []
    index = 2
    for _ in range(n):
        problems.append([int(input[i]) for i in range(index, index + k)])
        index += k

    from itertools import combinations

    for r in range(1, n + 1):
        for combo in combinations(range(n), r):
            if all(sum(problems[i][j] for i in combo) <= r // 2 for j in range(k)):
                print("YES")
                return
    print("NO")

if __name__ == "__main__":
    main()
